#!/usr/bin/env python3
"""Week 5 · harness for Task 3. Do not edit this file.

Builds a synthetic routing table that looks like the real thing - mostly /24s,
a long tail of shorter prefixes, a default route - and then asks it a lot of
questions.

    table      5,000 prefixes
    queries    20,000 addresses, drawn to hit the table the way real traffic does
    checked    every answer must equal the linear table's answer

    python3 bench.py
    python3 bench.py --yours
"""
import argparse, random, time

SEED, ROUTES, QUERIES = 246, 5_000, 20_000


def build(seed=SEED):
    rng = random.Random(seed)
    routes = [(0, 0, "default")]
    seen = {(0, 0)}
    # Real tables are dominated by /24, with a tail of shorter aggregates.
    lengths = [24] * 60 + [22] * 12 + [20] * 10 + [16] * 10 + [12] * 5 + [8] * 3
    while len(routes) < ROUTES:
        plen = rng.choice(lengths)
        mask = (0xFFFFFFFF << (32 - plen)) & 0xFFFFFFFF
        net = rng.getrandbits(32) & mask
        if (net, plen) in seen:
            continue
        seen.add((net, plen))
        routes.append((net, plen, f"hop{len(routes)}"))
    # Ask about addresses inside known prefixes most of the time, as traffic does.
    queries = []
    for _ in range(QUERIES):
        if rng.random() < 0.85:
            net, plen, _ = routes[rng.randrange(1, len(routes))]
            queries.append(net | rng.getrandbits(32 - plen))
        else:
            queries.append(rng.getrandbits(32))
    return routes, queries


def run(cls, label, routes, queries, reference=None):
    t0 = time.perf_counter()
    table = cls()
    for net, plen, hop in routes:
        table.add(net, plen, hop)
    build_s = time.perf_counter() - t0

    t0 = time.perf_counter()
    answers = [table.lookup(a) for a in queries]
    lookup_s = time.perf_counter() - t0

    wrong = 0 if reference is None else sum(
        1 for a, b in zip(answers, reference) if a != b)
    print(f"  {label:<10} build {build_s:>6.2f}s   lookup {lookup_s:>7.3f}s   "
          f"{len(queries) / lookup_s:>10,.0f} lookups/s"
          + (f"   wrong {wrong}" if reference is not None else ""))
    return {"build": build_s, "lookup": lookup_s, "answers": answers, "wrong": wrong}


def main():
    p = argparse.ArgumentParser()
    p.add_argument("--yours", action="store_true")
    a = p.parse_args()

    routes, queries = build()
    print(f"\n  {len(routes):,} prefixes, {len(queries):,} queries\n")

    from task3_lpm import LinearTable
    base = run(LinearTable, "baseline", routes, queries)

    if a.yours:
        from task3_lpm import YourTable
        mine = run(YourTable, "yours", routes, queries, base["answers"])
        print()
        if mine["wrong"]:
            print(f"   FAIL  {mine['wrong']:,} of {len(queries):,} answers differ "
                  f"from the linear table. Correctness first.")
        else:
            speedup = base["lookup"] / mine["lookup"]
            print(f"   ok    every answer matches")
            print(f"   lookup speedup  {speedup:>6.1f}x")
            grade = ("strong" if speedup >= 1000 else
                     "good" if speedup >= 100 else
                     "pass" if speedup > 2 else "not yet")
            print(f"\n   -> {grade}")
    print()


if __name__ == "__main__":
    main()
